extension DiagnosticDecorator {
  /// Decorates a ``DiagnosticMessage`` instance by delegating to the `decorateMessage(_:basedOnSeverity:)` method.
  ///
  /// - Parameter diagnosticMessage: The ``DiagnosticMessage`` instance that encapsulates both the message and its severity level.
  ///
  /// - Returns: A decorated version of the diagnostic message, determined by its severity level.
  func decorateDiagnosticMessage(_ diagnosticMessage: DiagnosticMessage) -> String {
    decorateMessage(
      diagnosticMessage.message,
      basedOnSeverity: diagnosticMessage. severity,
      categoryChain: diagnosticMessage.categoryChain
    )
  }
}
extension Parser {
  private class TokenMissingMaker: SyntaxRewriter {
    override func visit(_ token: TokenSyntax) -> TokenSyntax {
      TokenSyntax(token.tokenKind, presence: .missing) }
  }

  /// Creates a replicate of `syntax` with all tokens marked as missing.
  func withAllTokensMarkedMissing<T: RawSyntaxNodeProtocol>(syntax: T) -> T {
    let tokenMissingMaker = TokenMissingMaker(rawAllocationArena: self.arena)
    let allMissing = tokenMissingMaker.rewrite(
      Syntax(raw: RawSyntax(syntax), rawNodeArena: self.arena)
    ).raw
    return allMissing.cast(T.self)
  }
}

